const STUDENT_HTML = "<!DOCTYPE html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>مكتب الشهادات والتوصيات</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@400;500;600;700&family=Tinos:wght@400;700&family=Arimo:wght@400;700&family=Amiri:wght@400;700&family=Fraunces:wght@400;600&family=Source+Serif+4:wght@400;600&family=Reem+Kufi:wght@500;700&display=swap\">\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js\" defer></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js\" defer></script>\n<style>\n/* Layout: one narrow column, framed like the certificates it issues */\n:root{\n  --bg:#F4F5F2; --surface:#FFFFFF; --ink:#2C2A21; --muted:#6C6A5B; --line:#DEDDD3;\n  --frame:#4B4733; --accent:#2F6E8C; --accent-soft:#E3EEF3; --accent-ink:#FFFFFF;\n  --ok:#1F7A4A; --ok-bg:#E2F1E8; --warn:#9A5B00; --warn-bg:#FBEFD8; --bad:#A23A2E; --bad-bg:#F7E2DE; --info:#5B4B8A; --info-bg:#ECE8F6;\n  --ui:\"IBM Plex Sans Arabic\",\"Segoe UI\",Tahoma,sans-serif; --serif:\"Tinos\",\"Times New Roman\",serif; --paper:#FFFFFF;\n}\n@media (prefers-color-scheme: dark){\n  :root{ --bg:#16160F; --surface:#201F17; --ink:#ECEADF; --muted:#A6A392; --line:#38362A;\n    --frame:#BDB58E; --accent:#7DB8D4; --accent-soft:#1D3340; --accent-ink:#0D1F28;\n    --ok:#73D19D; --ok-bg:#163223; --warn:#F2B866; --warn-bg:#3A2A10; --bad:#F0948A; --bad-bg:#3A1C18; --info:#B9A9F0; --info-bg:#2A2440; color-scheme:dark; }\n}\n*{box-sizing:border-box}\nhtml,body{margin:0}\nbody{background:var(--bg);color:var(--ink);font:15px/1.65 var(--ui);}\n.wrap{max-width:760px;margin:0 auto;padding-block:24px 64px;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px))}\nh1,h2,h3{line-height:1.3;margin:0;text-wrap:balance}\nh1{font-size:23px;font-weight:700} h2{font-size:18px;font-weight:700} h3{font-size:15px;font-weight:600}\np{margin:0}\n.muted{color:var(--muted)} .small{font-size:13px}\n.brandbar{display:flex;align-items:center;gap:12px;justify-content:space-between;padding-bottom:16px;margin-bottom:20px;border-bottom:3px double var(--frame)}\n.brandbar .t{display:flex;flex-direction:column;min-width:0}\n.brandbar .t span{font-family:var(--serif);letter-spacing:.14em;text-transform:uppercase;font-size:11px;color:var(--accent)}\n.panel{background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:20px}\n.stack{display:flex;flex-direction:column;gap:16px}\n.row{display:flex;gap:12px;flex-wrap:wrap}.row>*{flex:1 1 200px;min-width:0}\nlabel{display:flex;flex-direction:column;gap:6px;font-weight:500;font-size:14px}\nlabel .hint{font-weight:400;color:var(--muted);font-size:12.5px}\ninput,select,textarea{font:inherit;color:var(--ink);background:var(--bg);border:1px solid var(--line);border-radius:8px;padding:10px 12px;width:100%}\ntextarea{min-height:96px;resize:vertical}\ninput:focus,select:focus,textarea:focus,button:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n[dir=ltr]{text-align:left}\nbutton,.btnlink{font:inherit;cursor:pointer;border-radius:8px;border:1px solid transparent;padding:10px 16px;font-weight:600;text-decoration:none;display:inline-flex;align-items:center;gap:6px}\n.btn{background:var(--accent);color:var(--accent-ink)} .btn2{background:transparent;color:var(--accent);border-color:var(--accent)} .btn3{background:transparent;color:var(--muted);border-color:var(--line)}\nbutton:disabled{opacity:.55;cursor:default}\n.tabs{display:flex;gap:4px;background:var(--bg);border:1px solid var(--line);border-radius:10px;padding:4px}\n.tabs button{flex:1;background:transparent;color:var(--muted);padding:8px 6px;font-size:14px}\n.tabs button[aria-selected=true]{background:var(--surface);color:var(--ink);box-shadow:0 1px 2px rgba(0,0,0,.08)}\n.err{background:var(--bad-bg);color:var(--bad);padding:10px 12px;border-radius:8px;font-size:14px}\n.okmsg{background:var(--ok-bg);color:var(--ok);padding:10px 12px;border-radius:8px;font-size:14px}\n.avatar{width:44px;height:44px;border-radius:50%;object-fit:cover;background:var(--line);flex:none}\n.photo-pick{display:flex;align-items:center;gap:14px}.photo-pick .avatar{width:72px;height:72px}\n.me{display:flex;align-items:center;gap:10px;flex:none}\n.choices{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}\n.choice{text-align:start;background:var(--surface);border:1px solid var(--line);color:var(--ink);padding:16px;border-radius:10px;display:flex;flex-direction:column;align-items:flex-start;gap:4px;font-weight:400}\n.choice b{font-size:15px} .choice:hover{border-color:var(--accent)}\n.choice[aria-pressed=true]{border-color:var(--accent);background:var(--accent-soft)}\n.tpls{display:grid;gap:10px}\n.tpl{flex-direction:row;justify-content:space-between;align-items:center;width:100%}\n.en{font-family:var(--serif);direction:ltr;text-align:left}\n.card{background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:16px;display:flex;flex-direction:column;gap:10px}\n.card-h{display:flex;justify-content:space-between;align-items:flex-start;gap:10px;flex-wrap:wrap}\n.chip{display:inline-flex;align-items:center;gap:6px;font-size:12.5px;font-weight:600;padding:3px 10px;border-radius:999px;white-space:nowrap}\n.chip::before{content:\"\";width:7px;height:7px;border-radius:50%;background:currentColor}\n.s-submitted{background:var(--warn-bg);color:var(--warn)} .s-needs_info{background:var(--bad-bg);color:var(--bad)}\n.s-edit_requested{background:var(--info-bg);color:var(--info)} .s-approved{background:var(--ok-bg);color:var(--ok)} .s-rejected{background:var(--line);color:var(--muted)}\n.meta{display:flex;gap:14px;flex-wrap:wrap;font-size:13px;color:var(--muted);font-variant-numeric:tabular-nums}\n.note{border-inline-start:3px solid var(--accent);padding:6px 12px;background:var(--accent-soft);border-radius:0 6px 6px 0;font-size:14px}\n.actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center}\n.radio{flex-direction:row;align-items:center;gap:8px;font-weight:400}.radio input{width:auto}\n.empty{text-align:center;padding:28px 16px;color:var(--muted);border:1px dashed var(--line);border-radius:10px}\n.spin{display:inline-block;width:14px;height:14px;border:2px solid currentColor;border-top-color:transparent;border-radius:50%;animation:s .8s linear infinite;vertical-align:-2px}\n@keyframes s{to{transform:rotate(360deg)}}\n@media (prefers-reduced-motion:reduce){.spin{animation:none}}\n.toast{position:fixed;bottom:calc(20px + env(safe-area-inset-bottom,0px));left:50%;transform:translateX(-50%);background:var(--ink);color:var(--surface);padding:10px 16px;border-radius:8px;font-size:14px;max-width:calc(100% - 32px);z-index:5}\n[hidden]{display:none!important}\n\n#stage{position:fixed;left:-30000px;top:0;direction:ltr}\n.pg{position:relative;background:var(--paper);overflow:hidden;color:#3F3B2C;flex:none}\n.pg.land{width:1123px;height:794px}\n.pg.port{width:794px;height:1123px}\n.pg img{max-width:none}\n/* formal (Mustaqbali-style) */\n.f .frame{position:absolute;inset:14px;border:3px solid var(--fr);}\n.f .frame::after{content:\"\";position:absolute;inset:6px;border:1.5px solid var(--fr)}\n.f .lt{position:absolute;top:38px;right:52px;height:36px}\n.f .lx{position:absolute;top:34px;left:52px;height:46px;max-width:200px;object-fit:contain}\n.f .lb{position:absolute;bottom:90px;right:46px;width:200px}\n.f.cert .center{position:absolute;top:118px;left:90px;right:90px;text-align:center;display:flex;flex-direction:column;align-items:center}\n.f .t{font-family:\"Tinos\",\"Times New Roman\",serif;color:var(--tc);font-size:50px;letter-spacing:.01em;text-transform:uppercase;line-height:1.1}\n.f .ct{font-family:\"Arimo\",Arial,sans-serif;font-size:27px;margin-top:50px;color:var(--ink2)}\n.f .nm{font-family:\"Arimo\",Arial,sans-serif;font-size:27px;letter-spacing:.02em;text-transform:uppercase;margin-top:22px;color:var(--ink2)}\n.f .ld{font-family:\"Arimo\",Arial,sans-serif;font-size:17px;margin-top:26px;line-height:1.55;color:var(--ink2)}\n.f .bd{font-family:\"Arimo\",Arial,sans-serif;font-size:17px;margin-top:16px;line-height:1.5;max-width:760px;color:var(--ink2)}\n.f .sig{position:absolute;left:104px;bottom:52px;width:262px;text-align:center;font-family:\"Tinos\",\"Times New Roman\",serif;font-size:17px;line-height:1.25;color:var(--ink2)}\n.f .sig img{width:262px;display:block}\n.f .sig .line{border-top:1px solid #5b5743;margin-top:60px}\n.f .ref{position:absolute;bottom:26px;left:0;right:0;text-align:center;font-family:\"Arimo\",Arial,sans-serif;font-size:10px;color:#9a9682;letter-spacing:.06em}\n.f[dir=rtl] .t{font-family:\"Amiri\",serif;text-transform:none;font-size:56px}\n.f[dir=rtl] .ct,.f[dir=rtl] .nm,.f[dir=rtl] .ld,.f[dir=rtl] .bd{font-family:\"IBM Plex Sans Arabic\",sans-serif}\n.f[dir=rtl] .sig{font-family:\"Amiri\",serif}\n/* formal letter */\n.f.letter .frame{inset:14px}\n.f.letter .lt{top:40px;right:52px;height:30px}\n.f.letter .lx{top:36px;left:56px;height:40px}\n.f.letter .lb{bottom:46px;right:50px;width:150px}\n.f.letter .lbody{position:absolute;top:120px;left:78px;right:78px;bottom:120px;overflow:hidden;font-family:\"Arimo\",Arial,sans-serif;font-size:13.5px;line-height:1.62;color:#2f2c22}\n.f.letter.cont .lbody{top:70px}\n.f.letter .lbody p{margin:0 0 12px;text-align:justify}\n.f.letter .date{margin-bottom:18px;color:#5a5646}\n.f.letter .sgb{margin-top:20px;font-family:\"Tinos\",serif;font-size:15px;line-height:1.3}\n.f.letter .sgb img{width:220px;display:block;margin:6px 0 4px}\n.f.letter .pno{position:absolute;bottom:36px;left:78px;font-family:\"Arimo\",Arial,sans-serif;font-size:10px;color:#9a9682}\n.f.letter[dir=rtl] .lbody{font-family:\"IBM Plex Sans Arabic\",sans-serif;font-size:14px;line-height:1.8}\n.f.letter[dir=rtl] .sgb{font-family:\"Amiri\",serif}\n/* modern (AI design) */\n.m{--a:#1F3A5F;--g:#A8843A}\n.m .band{position:absolute;top:0;bottom:0;left:0;width:30px;background:var(--a)}\n.m .band::after{content:\"\";position:absolute;top:0;bottom:0;right:-8px;width:3px;background:var(--g)}\n.m[dir=rtl] .band{left:auto;right:0}\n.m[dir=rtl] .band::after{right:auto;left:-8px}\n.m.cert .in{position:absolute;top:70px;bottom:60px;left:110px;right:90px;display:flex;flex-direction:column}\n.m[dir=rtl].cert .in{left:90px;right:110px}\n.m .logo{height:56px;max-width:220px;object-fit:contain;align-self:flex-start}\n.m .kicker{font-family:\"Arimo\",sans-serif;text-transform:uppercase;letter-spacing:.24em;font-size:12px;color:var(--g);margin-top:30px}\n.m .t{font-family:\"Fraunces\",serif;font-size:52px;color:var(--a);line-height:1.05;margin-top:8px}\n.m .pr{font-family:\"Arimo\",sans-serif;font-size:16px;color:#55534a;margin-top:34px}\n.m .nm{font-family:\"Fraunces\",serif;font-size:44px;color:#1d1c18;margin-top:6px;padding-bottom:10px;border-bottom:1px solid #d8d3c3;align-self:flex-start;min-width:55%}\n.m .ld{font-family:\"Source Serif 4\",serif;font-size:18px;color:#33312a;margin-top:18px;line-height:1.5;max-width:780px}\n.m .ft{margin-top:auto;display:flex;justify-content:space-between;align-items:flex-end;gap:20px;font-family:\"Arimo\",sans-serif;font-size:13px;color:#55534a}\n.m .ft .sg{text-align:center;min-width:240px}\n.m .ft .sg img{width:220px;display:block;margin:0 auto}\n.m .ft .sg img+b{border-top:0}\n.m .ft .sg b{display:block;font-family:\"Source Serif 4\",serif;font-size:16px;color:#1d1c18;border-top:1px solid #8f8a78;padding-top:6px}\n.m[dir=rtl] .t,.m[dir=rtl] .nm{font-family:\"Reem Kufi\",sans-serif}\n.m[dir=rtl] .ld,.m[dir=rtl] .pr,.m[dir=rtl] .ft,.m[dir=rtl] .kicker{font-family:\"IBM Plex Sans Arabic\",sans-serif;letter-spacing:0}\n.m.letter .head{position:absolute;top:52px;left:88px;right:70px;display:flex;justify-content:space-between;align-items:flex-start;gap:20px;padding-bottom:16px;border-bottom:2px solid var(--a)}\n.m[dir=rtl].letter .head{left:70px;right:88px}\n.m.letter .head .who{font-family:\"Arimo\",sans-serif;font-size:12px;color:#55534a;line-height:1.5}\n.m.letter .head .who b{display:block;font-family:\"Fraunces\",serif;font-size:19px;color:var(--a)}\n.m[dir=rtl].letter .head .who,.m[dir=rtl].letter .head .who b{font-family:\"IBM Plex Sans Arabic\",sans-serif}\n.m.letter .lbody{position:absolute;top:170px;left:88px;right:70px;bottom:90px;overflow:hidden;font-family:\"Source Serif 4\",serif;font-size:14px;line-height:1.65;color:#25231d}\n.m[dir=rtl].letter .lbody{left:70px;right:88px;font-family:\"IBM Plex Sans Arabic\",sans-serif;line-height:1.85}\n.m.letter.cont .lbody{top:70px}\n.m.letter .lbody p{margin:0 0 12px;text-align:justify}\n.m.letter .date{margin-bottom:18px;color:#6a675c}\n.m.letter .sgb{margin-top:18px;line-height:1.35}\n.m.letter .sgb img{width:210px;display:block;margin:6px 0 4px}\n.m.letter .pno{position:absolute;bottom:40px;left:88px;right:70px;font-family:\"Arimo\",sans-serif;font-size:10px;color:#8f8a78;display:flex;justify-content:space-between}\n.pv{width:100%;overflow:hidden;direction:ltr;border-radius:4px;background:#d6d4c8}\n.pv-inner{transform-origin:top left;direction:ltr;display:flex;flex-direction:column;gap:14px;width:max-content}\n\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <header class=\"brandbar\">\n    <div class=\"t\"><span>Certificates &amp; Recommendations</span><h1>مكتب الشهادات والتوصيات</h1></div>\n    <div class=\"me\" id=\"me\" hidden>\n      <img class=\"avatar\" id=\"meImg\" alt=\"\">\n      <div class=\"small\"><div id=\"meName\" style=\"font-weight:600\"></div><button class=\"btn3\" style=\"padding:2px 10px;font-size:12px\" data-act=\"logout\">خروج</button></div>\n    </div>\n  </header>\n  <main id=\"app\"><div class=\"empty\"><span class=\"spin\"></span> جاري التحميل</div></main>\n</div>\n<div id=\"stage\"></div>\n<div class=\"toast\" id=\"toast\" hidden></div>\n\n<script>\n/* ===== shared document renderer (used by the advisor dashboard and the student portal) ===== */\nconst DOCX={};\nconst esc=s=>String(s==null?'':s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst dmy=t=>{const d=new Date(t||Date.now());return String(d.getDate()).padStart(2,'0')+'/'+String(d.getMonth()+1).padStart(2,'0')+'/'+d.getFullYear();};\nconst longDate=(t,lang)=>new Date(t||Date.now()).toLocaleDateString(lang==='ar'?'ar-AE-u-nu-latn':'en-GB',{day:'numeric',month:'long',year:'numeric'});\nconst img=(src,cls)=>src?`<img class=\"${cls}\" src=\"${esc(src)}\" crossorigin=\"anonymous\" alt=\"\">`:'';\nfunction L(c){ const ar=c.lang==='ar'; const b=c.brand;\n  return { signatory: (ar?b.signatory_ar:b.signatory_en)||b.signatory_en||'', role:(ar?b.role_ar:b.role_en)||b.role_en||'', org:(ar?b.org_ar:b.org_en)||'', ar }; }\n\nfunction certPage(c){\n  const b=c.brand, l=L(c), f=c.fields; const dir=l.ar?'rtl':'ltr';\n  if(b.template==='modern'){\n    const logo=c.extraLogo||b.logoTop;\n    return `<div class=\"pg land m cert\" dir=\"${dir}\" style=\"--a:${esc(b.accent||'#1F3A5F')};--g:${esc(b.gold||'#A8843A')}\"><div class=\"band\"></div><div class=\"in\">\n      ${logo?img(logo,'logo'):''}\n      <div class=\"kicker\">${esc(l.org||b.label||'')}</div>\n      <div class=\"t\">${esc(f.title)}</div>\n      <div class=\"pr\">${l.ar?'تُمنح هذه الشهادة إلى':'This certificate is presented to'}</div>\n      <div class=\"nm\">${esc(c.name)}</div>\n      <div class=\"ld\">${esc(f.lead)} <b>${esc(f.program)}</b>${f.program&&!l.ar?'.':''}${f.body?' '+esc(f.body):''}</div>\n      <div class=\"ft\"><div>${dmy(c.date)}<br><span style=\"font-size:10px;color:#9a9682\">Ref ${esc(c.ref)}${c.verify?' · '+esc(c.verify):''}</span></div>\n        <div class=\"sg\">${img(b.signature,'')}<b>${esc(l.signatory)}</b>${esc(l.role)}</div></div>\n    </div></div>`;\n  }\n  return `<div class=\"pg land f cert\" dir=\"${dir}\" style=\"--fr:${esc(b.frameColor||'#4B4733')};--tc:${esc(b.titleColor||'#6FA6C0')};--ink2:${esc(b.inkColor||'#46412F')}\">\n    <div class=\"frame\"></div>${img(b.logoTop,'lt')}${img(c.extraLogo,'lx')}\n    <div class=\"center\">\n      <div class=\"t\">${esc(f.title)}</div>\n      <div class=\"ct\">${l.ar?(c.gender==='f'?'تشهد هذه الوثيقة بأن الطالبة':'تشهد هذه الوثيقة بأن الطالب'):'This certifies that'}</div>\n      <div class=\"nm\">${esc(c.name)}</div>\n      <div class=\"ld\">${esc(f.lead)}<br><b>${esc(f.program)}</b>${f.program&&!l.ar?'.':''}</div>\n      ${f.body?`<div class=\"bd\">${esc(f.body)}</div>`:''}\n    </div>\n    <div class=\"sig\">${b.signature?img(b.signature,''):'<div class=\"line\"></div>'}<div>${esc(l.signatory)}</div><div>${esc(l.role)}</div><div>${dmy(c.date)}</div></div>\n    ${img(b.logoBottom,'lb')}\n    <div class=\"ref\">REF ${esc(c.ref)}${c.verify?' · VERIFY: '+esc(c.verify):''}</div>\n  </div>`;\n}\n\nfunction letterPages(host,c){\n  const b=c.brand,l=L(c),dir=l.ar?'rtl':'ltr',modern=b.template==='modern';\n  const paras=String(c.letter||'').split(/\\n\\s*\\n/).map(s=>s.trim()).filter(Boolean);\n  const units=[`<div class=\"date\">${esc(longDate(c.date,c.lang))}</div>`,...paras.map(p=>`<p>${esc(p).replace(/\\n/g,'<br>')}</p>`),\n    `<div class=\"sgb\">${l.ar?'وتفضلوا بقبول فائق الاحترام والتقدير،':'Sincerely,'}${img(b.signature,'')}<b>${esc(l.signatory)}</b><br>${esc(l.role)}${l.org?'<br>'+esc(l.org):''}${b.email?'<br>'+esc(b.email):''}${b.phone?'<br>'+esc(b.phone):''}</div>`];\n  const pages=[];\n  const mk=(first)=>{ const d=document.createElement('div');\n    if(modern){ d.className='pg port m letter'+(first?'':' cont'); d.style.cssText=`--a:${b.accent||'#1F3A5F'};--g:${b.gold||'#A8843A'}`;\n      d.innerHTML=`<div class=\"band\"></div>${first?`<div class=\"head\"><div class=\"who\"><b>${esc(l.signatory)}</b>${esc(l.role)}${l.org?'<br>'+esc(l.org):''}</div>${img(c.extraLogo||b.logoTop,'logo')}</div>`:''}<div class=\"lbody\"></div><div class=\"pno\"><span>${esc(c.ref)}${c.verify?' · '+esc(c.verify):''}</span><span class=\"n\"></span></div>`; }\n    else { d.className='pg port f letter'+(first?'':' cont'); d.style.cssText=`--fr:${b.frameColor||'#4B4733'};--tc:${b.titleColor||'#6FA6C0'}`;\n      d.innerHTML=`<div class=\"frame\"></div>${first?img(b.logoTop,'lt')+img(c.extraLogo,'lx'):''}<div class=\"lbody\"></div>${img(b.logoBottom,'lb')}<div class=\"pno\"><span class=\"n\"></span> ${esc(c.ref)}${c.verify?' · '+esc(c.verify):''}</div>`; }\n    d.setAttribute('dir',dir); host.appendChild(d); pages.push(d); return d.querySelector('.lbody'); };\n  let body=mk(true);\n  units.forEach(u=>{ const t=document.createElement('div'); t.innerHTML=u; const el=t.firstElementChild; body.appendChild(el);\n    if(body.scrollHeight>body.clientHeight+1&&body.children.length>1){ body.removeChild(el); body=mk(false); body.appendChild(el);} });\n  pages.forEach((p,i)=>{ const n=p.querySelector('.n'); if(n) n.textContent=pages.length>1?(i+1)+' / '+pages.length+' ·':''; });\n  return pages;\n}\n\nlet fontsReady=null;\nfunction ensureFonts(){ if(!fontsReady) fontsReady=Promise.all(['27px Arimo','bold 17px Arimo','50px Tinos','17px Tinos','56px Amiri','17px \"IBM Plex Sans Arabic\"','52px Fraunces','18px \"Source Serif 4\"','44px \"Reem Kufi\"'].map(f=>document.fonts.load(f).catch(()=>{}))).then(()=>document.fonts.ready); return fontsReady; }\nfunction buildPages(host,c){\n  host.innerHTML='';\n  if(c.type==='rec') return letterPages(host,c);\n  host.innerHTML=certPage(c); return [host.firstElementChild];\n}\nasync function drawPreviewInto(pv,c){\n  await ensureFonts();\n  const inner=document.createElement('div'); inner.className='pv-inner';\n  pv.innerHTML=''; pv.appendChild(inner);\n  const pages=buildPages(inner,c);\n  const w=pages[0]?pages[0].offsetWidth:794; const sc=pv.clientWidth/w;\n  inner.style.transform='scale('+sc+')';\n  pv.style.height=(inner.scrollHeight*sc)+'px';\n  return pages.length;\n}\nasync function makePdf(c){\n  await ensureFonts();\n  const stage=document.getElementById('stage');\n  const pages=buildPages(stage,c);\n  await Promise.all([...stage.querySelectorAll('img')].map(im=>im.complete?0:new Promise(res=>{im.onload=im.onerror=res;})));\n  const land=c.type!=='rec';\n  const pdf=new window.jspdf.jsPDF({orientation:land?'landscape':'portrait',unit:'pt',format:'a4',compress:true});\n  const W=pdf.internal.pageSize.getWidth(),H=pdf.internal.pageSize.getHeight();\n  for(let i=0;i<pages.length;i++){\n    const cv=await html2canvas(pages[i],{scale:2,useCORS:true,backgroundColor:'#ffffff',logging:false,onclone:(doc)=>{const s=doc.getElementById('stage');if(s)s.style.left='0';}});\n    if(i) pdf.addPage('a4',land?'landscape':'portrait');\n    pdf.addImage(cv.toDataURL('image/jpeg',0.92),'JPEG',0,0,W,H);\n  }\n  stage.innerHTML='';\n  const fname=(c.type==='rec'?'Recommendation':'Certificate')+' - '+String(c.name).replace(/[\\\\/:*?\"<>|]/g,'')+' - '+c.ref+'.pdf';\n  return {blob:pdf.output('blob'),fname};\n}\n\n</script>\n<script>\nconst S={af:{},token:null,profile:null,items:[],templates:[],view:'auth',authTab:'login',mode:null,editId:null,form:{},busy:'',err:'',info:''};\ntry{S.token=localStorage.getItem('cr_token');}catch(e){}\nconst $=(s,r=document)=>r.querySelector(s);\nconst STATUS={submitted:'قيد المراجعة',needs_info:'مطلوب منك تعديل',edit_requested:'طلب تعديل مرسل',approved:'معتمدة – جاهزة للتحميل',rejected:'مرفوض'};\nconst fmt=t=>t?new Date(t).toLocaleDateString('ar-AE-u-nu-latn',{day:'numeric',month:'short',year:'numeric'}):'';\nfunction toast(m){const t=$('#toast');t.textContent=m;t.hidden=false;clearTimeout(toast._t);toast._t=setTimeout(()=>t.hidden=true,3800);}\nfunction setToken(t){S.token=t;try{t?localStorage.setItem('cr_token',t):localStorage.removeItem('cr_token');}catch(e){}}\n\nasync function api(path,opts={}){\n  try{\n    const r=await fetch('/api/'+path,{method:opts.method||(opts.body?'POST':'GET'),headers:{'content-type':'application/json',...(S.token?{authorization:'Bearer '+S.token}:{})},body:opts.body?JSON.stringify(opts.body):undefined});\n    const j=await r.json().catch(()=>({ok:false,error:'خطأ غير متوقع'}));\n    if(r.status===401&&S.token&&!opts.noLogout){ setToken(null); S.profile=null; S.view='auth'; S.err='انتهت الجلسة، سجّل الدخول من جديد.'; render(); }\n    return j;\n  }catch(e){ return {ok:false,error:'تعذر الاتصال، تأكد من الإنترنت وحاول مرة ثانية.'}; }\n}\n\n/* photos */\nfunction loadImg(src){return new Promise((res,rej)=>{const i=new Image();i.onload=()=>res(i);i.onerror=()=>rej(new Error('صيغة الصورة غير مدعومة'));i.src=src;});}\nasync function squareThumb(file){\n  const url=URL.createObjectURL(file); const img=await loadImg(url); URL.revokeObjectURL(url);\n  const s=Math.min(img.width,img.height); const c=document.createElement('canvas'); c.width=c.height=160;\n  c.getContext('2d').drawImage(img,(img.width-s)/2,(img.height-s)/2,s,s,0,0,160,160);\n  return c.toDataURL('image/jpeg',0.8);\n}\n\n/* CV text extraction (in the browser; the file itself is never uploaded) */\nfunction loadScript(src){return new Promise((res,rej)=>{const s=document.createElement('script');s.src=src;s.onload=res;s.onerror=()=>rej(new Error('تعذر تحميل أداة القراءة'));document.head.appendChild(s);});}\nasync function extractCv(file){\n  const buf=await file.arrayBuffer(); const name=file.name.toLowerCase();\n  if(name.endsWith('.pdf')||file.type==='application/pdf'){\n    if(!window.pdfjsLib){ await loadScript('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js'); await loadScript('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js'); }\n    const pdf=await window.pdfjsLib.getDocument({data:buf}).promise; let out='';\n    for(let i=1;i<=Math.min(pdf.numPages,8);i++){ const tc=await (await pdf.getPage(i)).getTextContent(); out+=tc.items.map(x=>x.str).join(' ')+'\\n'; }\n    return out;\n  }\n  if(name.endsWith('.docx')){\n    if(!window.mammoth) await loadScript('https://cdnjs.cloudflare.com/ajax/libs/mammoth/1.6.0/mammoth.browser.min.js');\n    return (await window.mammoth.extractRawText({arrayBuffer:buf})).value;\n  }\n  throw new Error('ارفع السيرة بصيغة PDF أو Word (docx)، أو الصق نصها.');\n}\n\n/* render */\nfunction render(){\n  const me=$('#me');\n  if(S.profile){ me.hidden=false; $('#meName').textContent=S.profile.name||S.profile.username; const im=$('#meImg'); if(S.profile.photo) im.src=S.profile.photo; else im.removeAttribute('src'); }\n  else me.hidden=true;\n  $('#app').innerHTML=S.view==='auth'?authView():S.view==='form'?formView():homeView();\n  bind();\n}\n\nfunction authView(){\n  const t=S.authTab;\n  return `<div class=\"panel stack\" style=\"max-width:460px;margin:0 auto\">\n    <p class=\"muted\">من هنا تطلب شهادة أو رسالة توصية من مرشدك الأكاديمي، وتتابع حالتها وتحمّلها بأي وقت.</p>\n    <div class=\"tabs\" role=\"tablist\">\n      <button role=\"tab\" aria-selected=\"${t==='login'}\" data-act=\"authTab\" data-v=\"login\">دخول</button>\n      <button role=\"tab\" aria-selected=\"${t==='register'}\" data-act=\"authTab\" data-v=\"register\">حساب جديد</button>\n      <button role=\"tab\" aria-selected=\"${t==='reset'}\" data-act=\"authTab\" data-v=\"reset\">نسيت كلمة المرور</button>\n    </div>\n    ${S.err?`<div class=\"err\">${esc(S.err)}</div>`:''}${S.info?`<div class=\"okmsg\">${esc(S.info)}</div>`:''}\n    <form id=\"authForm\" class=\"stack\" novalidate>\n    ${t==='login'?`\n      <label>اسم المستخدم<input id=\"a_user\" value=\"${esc(S.af.a_user||'')}\" dir=\"ltr\" autocomplete=\"username\" autocapitalize=\"none\"></label>\n      <label>كلمة المرور<input id=\"a_pass\" type=\"password\" dir=\"ltr\" autocomplete=\"current-password\"></label>\n      <button class=\"btn\" type=\"submit\">${S.busy?'<span class=\"spin\"></span> ':''}دخول</button>`\n    :t==='register'?`\n      <div class=\"photo-pick\">\n        <img class=\"avatar\" id=\"r_prev\" alt=\"\" ${S.regPhoto?`src=\"${S.regPhoto}\"`:''}>\n        <label style=\"flex:1\">صورتك الشخصية<span class=\"hint\">عشان يتذكرك المرشد. صورة واضحة للوجه.</span><input id=\"r_photo\" type=\"file\" accept=\"image/*\"></label>\n      </div>\n      <label>الاسم الكامل<input id=\"r_name\" value=\"${esc(S.af.r_name||'')}\" autocomplete=\"name\"></label>\n      <label>اسم المستخدم<span class=\"hint\">حروف إنجليزية أو أرقام، مثل abdulla.f</span><input id=\"r_user\" value=\"${esc(S.af.r_user||'')}\" dir=\"ltr\" autocomplete=\"username\" autocapitalize=\"none\"></label>\n      <label>الإيميل<span class=\"hint\">أي إيميل، للتواصل معك</span><input id=\"r_email\" value=\"${esc(S.af.r_email||'')}\" type=\"email\" dir=\"ltr\" autocomplete=\"email\"></label>\n      <label>كلمة المرور<span class=\"hint\">8 أحرف أو أكثر</span><input id=\"r_pass\" type=\"password\" dir=\"ltr\" autocomplete=\"new-password\"></label>\n      <button class=\"btn\" type=\"submit\">${S.busy?'<span class=\"spin\"></span> ':''}إنشاء الحساب</button>`\n    :`\n      <p class=\"small muted\">تواصل مع المرشد يعطيك رمز استعادة، ثم اكتبه هنا مع كلمة المرور الجديدة.</p>\n      <label>اسم المستخدم<input id=\"x_user\" value=\"${esc(S.af.x_user||'')}\" dir=\"ltr\" autocapitalize=\"none\"></label>\n      <label>رمز الاستعادة<input id=\"x_code\" value=\"${esc(S.af.x_code||'')}\" inputmode=\"numeric\" dir=\"ltr\" maxlength=\"6\"></label>\n      <label>كلمة مرور جديدة<input id=\"x_pass\" type=\"password\" dir=\"ltr\" autocomplete=\"new-password\"></label>\n      <button class=\"btn\" type=\"submit\">${S.busy?'<span class=\"spin\"></span> ':''}تغيير كلمة المرور والدخول</button>`}\n    </form></div>`;\n}\n\nfunction homeView(){\n  const done=S.items.filter(i=>i.status==='approved').length, open=S.items.filter(i=>!['approved','rejected'].includes(i.status)).length;\n  return `<div class=\"stack\">\n    ${S.profile&&!S.profile.photo?`<div class=\"note\">أضف صورتك الشخصية عشان يتعرف عليك المرشد. <label class=\"btn2\" style=\"display:inline-flex;padding:4px 10px;margin-inline-start:6px;cursor:pointer\">رفع صورة<input id=\"p_photo\" type=\"file\" accept=\"image/*\" hidden></label></div>`:''}\n    <section class=\"stack\"><h2>اطلب وثيقة</h2>\n      <div class=\"choices\">\n        ${S.templates.length?`<button class=\"choice\" data-act=\"new\" data-v=\"tpl\"><b>شهادة جاهزة</b><span class=\"small muted\">نماذج معتمدة مسبقاً، تكتب اسمك وبس</span></button>`:''}\n        <button class=\"choice\" data-act=\"new\" data-v=\"cert\"><b>شهادة تقدير أو مشاركة</b><span class=\"small muted\">اكتب إنجازك وبنصيغه بدقة</span></button>\n        <button class=\"choice\" data-act=\"new\" data-v=\"rec\"><b>رسالة توصية</b><span class=\"small muted\">ارفع سيرتك الذاتية وأهم إنجازاتك</span></button>\n      </div></section>\n    <section class=\"stack\">\n      <div class=\"card-h\"><h2>طلباتي</h2><span class=\"meta\">${done} جاهزة · ${open} قيد العمل</span></div>\n      ${S.items.length?S.items.map(itemCard).join(''):`<div class=\"empty\">ما عندك طلبات للحين. اختر نوع الوثيقة من فوق وابدأ.</div>`}\n    </section></div>`;\n}\nfunction itemTitle(i){\n  if(i.type==='rec') return 'رسالة توصية'+(i.input.target?' — '+i.input.target:'');\n  const p=i.title?{title:i.title,program:i.program}:(i.input.polished||{});\n  return (p.title||'شهادة')+((p.program||i.input.program)?' — '+(p.program||i.input.program):'');\n}\nfunction itemCard(i){\n  const open=['submitted','needs_info','edit_requested'].includes(i.status);\n  const canEdit=['submitted','needs_info'].includes(i.status);\n  const wait=i.nextReminderAt&&i.nextReminderAt>Date.now();\n  const d=i.input.delivery;\n  return `<article class=\"card\">\n    <div class=\"card-h\"><div><h3>${esc(itemTitle(i))}</h3><div class=\"meta\"><span>${esc(i.id)}</span><span>أُرسل ${fmt(i.createdAt)}</span>${i.approvedAt?`<span>اعتُمد ${fmt(i.approvedAt)}</span>`:''}${i.input.deadline?`<span>الموعد النهائي ${esc(i.input.deadline)}</span>`:''}</div></div>\n      <span class=\"chip s-${i.status}\">${STATUS[i.status]||i.status}</span></div>\n    ${i.advisorNote?`<div class=\"note\"><b>ملاحظة المرشد:</b> ${esc(i.advisorNote)}</div>`:''}\n    ${i.status==='edit_requested'&&i.studentNote?`<div class=\"small muted\">طلبك: ${esc(i.studentNote)}</div>`:''}\n    ${i.type==='rec'&&d?`<div class=\"small muted\">التسليم: ${d.mode==='self'?'لك':d.mode==='email'?'إلى '+esc(d.email):'رفع على '+esc(d.platform)}${i.sentAt?` · تم ${fmt(i.sentAt)}`:''}</div>`:''}\n    <div class=\"actions\">\n      ${i.status==='approved'?`<button class=\"btn\" data-act=\"download\" data-id=\"${esc(i.id)}\">تحميل PDF</button>`:''}\n      ${canEdit?`<button class=\"btn2\" data-act=\"edit\" data-id=\"${esc(i.id)}\">تعديل بيانات الطلب</button>`:''}\n      ${open?`<button class=\"btn3\" data-act=\"remind\" data-id=\"${esc(i.id)}\" ${wait?'disabled':''}>${wait?'تذكير متاح '+fmt(i.nextReminderAt):'إرسال تذكير'}</button>`:''}\n      ${['approved','rejected'].includes(i.status)?`<button class=\"btn3\" data-act=\"askEdit\" data-id=\"${esc(i.id)}\">طلب تعديل</button>`:''}\n    </div>\n    <div class=\"stack\" id=\"ask-${esc(i.id)}\" hidden>\n      <label>وش التعديل اللي تبيه؟<textarea id=\"ask_${esc(i.id)}\" placeholder=\"مثال: الاسم الصحيح Abdulla Obaid Alfalasi\"></textarea></label>\n      <div class=\"actions\"><button class=\"btn\" data-act=\"sendEdit\" data-id=\"${esc(i.id)}\">إرسال طلب التعديل</button></div>\n    </div></article>`;\n}\n\n/* forms */\nconst F=()=>S.form;\nfunction field(id,label,o={}){\n  const v=F()[id]??''; const hint=o.hint?`<span class=\"hint\">${o.hint}</span>`:'';\n  if(o.area) return `<label>${label}${hint}<textarea id=\"f_${id}\" data-k=\"${id}\" ${o.ph?`placeholder=\"${esc(o.ph)}\"`:''}>${esc(v)}</textarea></label>`;\n  return `<label>${label}${hint}<input id=\"f_${id}\" data-k=\"${id}\" value=\"${esc(v)}\" ${o.type?`type=\"${o.type}\"`:''} ${o.ltr?'dir=\"ltr\"':''} ${o.ph?`placeholder=\"${esc(o.ph)}\"`:''}></label>`;\n}\nfunction commonFields(withLang=true){\n  return `<div class=\"row\">${field('name','الاسم كما تبيه في الوثيقة',{hint:'بنفس لغة الوثيقة'})}${field('contactEmail','إيميل التواصل',{type:'email',ltr:true})}</div>\n  <div class=\"row\"><label>الصيغة<select id=\"f_gender\" data-k=\"gender\"><option value=\"m\" ${F().gender!=='f'?'selected':''}>طالب</option><option value=\"f\" ${F().gender==='f'?'selected':''}>طالبة</option></select></label>\n  ${withLang?`<label>لغة الوثيقة<select id=\"f_lang\" data-k=\"lang\"><option value=\"en\" ${F().lang!=='ar'?'selected':''}>English</option><option value=\"ar\" ${F().lang==='ar'?'selected':''}>العربية</option></select></label>`:''}</div>`;\n}\nfunction miniPreview(p,name,lang){\n  const en=lang!=='ar';\n  return `<div class=\"panel\" style=\"border:3px double #4B4733;border-radius:2px;background:#fff;color:#3d3a2c;text-align:center;padding:16px\" dir=\"${en?'ltr':'rtl'}\">\n    <div style=\"font-family:var(--serif);color:#6FA6C0;font-size:21px;text-transform:uppercase\">${esc(p.title||'')}</div>\n    <div>${en?'This certifies that':'تشهد هذه الوثيقة بأن'}</div>\n    <div style=\"font-size:17px;letter-spacing:.03em;margin:4px 0\">${esc((name||(en?'YOUR NAME':'اسمك')).toUpperCase())}</div>\n    <div class=\"small\">${esc(p.lead||'')} <b>${esc(p.program||'')}</b></div>\n    ${p.body?`<div class=\"small\" style=\"margin-top:6px\">${esc(p.body)}</div>`:''}</div>`;\n}\nfunction formView(){\n  const m=S.mode,f=F(); let body='';\n  if(m==='tpl'){\n    const t=S.templates.find(x=>x.id===f.templateId);\n    body=`<div class=\"tpls\">${S.templates.map(x=>`<button type=\"button\" class=\"choice tpl\" aria-pressed=\"${x.id===f.templateId}\" data-act=\"pickTpl\" data-id=\"${esc(x.id)}\">\n      <span><b class=\"${x.lang==='en'?'en':''}\">${esc(x.label)}</b>${x.description?`<br><span class=\"small muted\">${esc(x.description)}</span>`:''}</span><span class=\"small muted\">${x.lang==='en'?'English':'عربي'}</span></button>`).join('')}</div>\n      ${t?`<div id=\"mp\">${miniPreview(t.fields,f.name,t.lang)}</div>`:''}\n      ${commonFields(false)}${field('achievement','ملاحظة للمرشد (اختياري)',{area:true,ph:'مثال: شاركت في الدفعة الثانية'})}`;\n  }else if(m==='cert'){\n    body=`${commonFields()}\n      <div class=\"row\">${field('program','اسم البرنامج أو الفعالية',{ph:'Silicon Valley Summer Program – Mustaqbali'})}${field('period','التاريخ أو الفترة',{ph:'2025'})}</div>\n      ${field('achievement','وش الإنجاز اللي قدمته؟',{area:true,hint:'اكتبه بأسلوبك وبالتفصيل. الذكاء الاصطناعي يصيغه بدقة والمرشد يراجعه.',ph:'مثال: قدت فريق من 4 أشخاص وفزنا بالمركز الأول في تحدي النقاط، وقدمت العرض النهائي...'})}`;\n  }else{\n    const d=f.delivery||{mode:'self'};\n    body=`${commonFields()}\n      ${field('target','على وش تقدّم؟',{hint:'البرنامج أو الوظيفة والجهة',ph:'MSc Computer Science – Imperial College London'})}\n      ${field('relationship','وش علاقتك بالمرشد؟',{area:true,hint:'كيف ومتى عرفك',ph:'طالب في برنامج مستقبلي – Silicon Valley Summer Program 2025'})}\n      <label>السيرة الذاتية<span class=\"hint\">PDF أو Word. الملف يُقرأ في جهازك ويوصل للمرشد نصه فقط.</span><input id=\"f_cv\" type=\"file\" accept=\".pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document\"></label>\n      ${S.busy==='cv'?`<div class=\"small muted\"><span class=\"spin\"></span> جاري قراءة السيرة…</div>`:f.cvName?`<div class=\"small muted\">تمت قراءة: ${esc(f.cvName)} (${(f.cvText||'').length} حرف)</div>`:''}\n      <details><summary class=\"small\" style=\"cursor:pointer\">أو الصق نص السيرة بنفسك</summary>${field('cvText','',{area:true})}</details>\n      ${field('achievements','أهم الإنجازات اللي تبي المرشد يذكرها',{area:true})}\n      ${field('skills','أهم المهارات',{area:true,ph:'قيادة الفريق، تحليل البيانات، Python، العرض والإلقاء'})}\n      ${field('deadline','آخر موعد للتسليم',{type:'date',ltr:true})}\n      <fieldset class=\"stack\" style=\"border:1px solid var(--line);border-radius:10px;padding:14px\"><legend style=\"padding:0 6px;font-weight:600\">وين تنرسل الرسالة؟</legend>\n        <label class=\"radio\"><input type=\"radio\" name=\"dm\" value=\"self\" data-dm ${d.mode==='self'?'checked':''}> أحملها أنا من هنا</label>\n        <label class=\"radio\"><input type=\"radio\" name=\"dm\" value=\"email\" data-dm ${d.mode==='email'?'checked':''}> المرشد يرسلها لإيميل جهة (الجامعة أو جهة العمل)</label>\n        <label class=\"radio\"><input type=\"radio\" name=\"dm\" value=\"platform\" data-dm ${d.mode==='platform'?'checked':''}> المرشد يرفعها على منصة</label>\n        ${d.mode==='email'?`<label>إيميل الجهة<input id=\"f_demail\" data-dk=\"email\" type=\"email\" dir=\"ltr\" value=\"${esc(d.email||'')}\"></label>`:''}\n        ${d.mode==='platform'?`<label>اسم المنصة<input id=\"f_dplat\" data-dk=\"platform\" value=\"${esc(d.platform||'')}\" placeholder=\"UCAS / Common App / بوابة الجامعة\"></label>\n          <label>الرابط<input id=\"f_dlink\" data-dk=\"link\" dir=\"ltr\" value=\"${esc(d.link||'')}\"></label>\n          <label>تعليمات الرفع<textarea id=\"f_dnotes\" data-dk=\"notes\" placeholder=\"مثال: بيوصلك إيميل دعوة من الجامعة باسمي\">${esc(d.notes||'')}</textarea></label>`:''}\n      </fieldset>`;\n  }\n  const head=m==='tpl'?'شهادة جاهزة':m==='cert'?'شهادة تقدير أو مشاركة':'رسالة توصية';\n  return `<form id=\"reqForm\" class=\"panel stack\" novalidate>\n    <div class=\"card-h\"><h2>${S.editId?'تعديل الطلب':head}</h2><button type=\"button\" class=\"btn3\" data-act=\"back\">رجوع</button></div>\n    ${S.err?`<div class=\"err\">${esc(S.err)}</div>`:''}\n    ${body}\n    ${S.editId?field('note','وش عدّلت؟ (يوصل للمرشد)'):''}\n    <div class=\"actions\"><button class=\"btn\" type=\"submit\" ${S.busy?'disabled':''}>${S.busy==='submit'?'<span class=\"spin\"></span> ':''}${S.editId?'حفظ وإعادة الإرسال':'إرسال للمرشد'}</button></div>\n  </form>`;\n}\n\nfunction bind(){\n  const app=$('#app');\n  app.querySelectorAll('[data-k]').forEach(el=>el.addEventListener('input',()=>{F()[el.dataset.k]=el.value; if(el.dataset.k==='name'&&S.mode==='tpl') refreshMini();}));\n  app.querySelectorAll('[data-dk]').forEach(el=>el.addEventListener('input',()=>{F().delivery[el.dataset.dk]=el.value;}));\n  app.querySelectorAll('[data-dm]').forEach(el=>el.addEventListener('change',()=>{F().delivery={...(F().delivery||{}),mode:el.value};render();}));\n  const cv=$('#f_cv'); if(cv) cv.addEventListener('change',async()=>{ const file=cv.files[0]; if(!file) return; S.busy='cv'; render();\n    try{ const t=(await extractCv(file)).replace(/\\s+\\n/g,'\\n').trim(); if(t.length<40) throw new Error('ما قدرنا نقرأ نص السيرة (يمكن صورة). الصق النص بنفسك.'); F().cvText=t.slice(0,15000); F().cvName=file.name; }catch(e){ toast(e.message); }\n    S.busy=''; render(); });\n  const rp=$('#r_photo'); if(rp) rp.addEventListener('change',async()=>{ try{ S.regPhoto=await squareThumb(rp.files[0]); $('#r_prev').src=S.regPhoto; }catch(e){ toast(e.message); } });\n  const pp=$('#p_photo'); if(pp) pp.addEventListener('change',async()=>{ try{ const ph=await squareThumb(pp.files[0]); const r=await api('photo',{body:{photo:ph}}); if(r.ok){ S.profile=r.profile; render(); toast('تم حفظ صورتك'); } else toast(r.error); }catch(e){ toast(e.message); } });\n  const af=$('#authForm'); if(af) af.addEventListener('submit',e=>{e.preventDefault();doAuth();});\n  const rf=$('#reqForm'); if(rf) rf.addEventListener('submit',e=>{e.preventDefault();submitForm();});\n}\nfunction refreshMini(){ const t=S.templates.find(x=>x.id===F().templateId); const mp=$('#mp'); if(t&&mp) mp.innerHTML=miniPreview(t.fields,F().name,t.lang); }\n\n/* actions */\nasync function doAuth(){\n  if(S.busy) return;\n  const t=S.authTab; let r;\n  document.querySelectorAll('#authForm input:not([type=file])').forEach(el=>{ if(el.type!=='password') S.af[el.id]=el.value; });\n  const pw={}; document.querySelectorAll('#authForm input[type=password]').forEach(el=>pw[el.id]=el.value);\n  const v=id=>id in pw?pw[id]:(S.af[id]||'');\n  S.err=''; S.info=''; S.busy='auth'; render();\n  if(t==='login') r=await api('login',{body:{username:v('a_user'),password:v('a_pass')},noLogout:true});\n  else if(t==='register') r=await api('register',{body:{name:v('r_name'),username:v('r_user'),email:v('r_email'),password:v('r_pass'),photo:S.regPhoto},noLogout:true});\n  else r=await api('reset',{body:{username:v('x_user'),code:v('x_code'),password:v('x_pass')},noLogout:true});\n  S.busy='';\n  if(!r.ok){ S.err=r.error; render(); return; }\n  setToken(r.token); await load();\n}\nasync function load(){\n  const r=await api('me');\n  if(!r.ok){ S.view='auth'; render(); return; }\n  S.profile=r.profile; S.items=r.items||[]; S.templates=r.templates||[]; S.view='home'; S.err=''; render();\n}\nfunction startForm(mode,item){\n  S.mode=mode; S.err=''; S.editId=item?item.id:null; const p=S.profile||{};\n  if(item){ S.form={name:item.name,contactEmail:item.contactEmail,gender:item.gender,lang:item.lang,...item.input,delivery:{...(item.input.delivery||{mode:'self'})}}; if(item.input.templateId) S.mode='tpl'; else S.mode=item.type; }\n  else S.form={name:p.name||'',contactEmail:p.email||'',gender:'m',lang:'en',delivery:{mode:'self'},templateId:mode==='tpl'&&S.templates[0]?S.templates[0].id:''};\n  S.view='form'; render(); scrollTo(0,0);\n}\nasync function submitForm(){\n  if(S.busy) return; S.busy='submit'; S.err=''; render();\n  const payload={...S.form,type:S.mode==='rec'?'rec':'cert'}; if(S.mode!=='tpl') delete payload.templateId;\n  const wasEdit=!!S.editId;\n  const r=wasEdit?await api('requests/'+encodeURIComponent(S.editId),{method:'PUT',body:payload}):await api('requests',{body:payload});\n  S.busy='';\n  if(!r.ok){ S.err=r.error; render(); scrollTo(0,0); return; }\n  S.items=r.items; S.view='home'; S.editId=null; render(); toast(wasEdit?'تم حفظ التعديل':'وصل طلبك للمرشد');\n}\nasync function download(id,btn){\n  btn.disabled=true; btn.innerHTML='<span class=\"spin\"></span> جاري التجهيز';\n  try{\n    const r=await api('requests/'+encodeURIComponent(id)+'/document');\n    if(!r.ok) throw new Error(r.error);\n    const c={...r.doc,verify:location.host+'/v/'+r.doc.ref};\n    const pdf=await makePdf(c);\n    const url=URL.createObjectURL(pdf.blob);\n    const a=document.createElement('a'); a.href=url; a.download=pdf.fname; document.body.appendChild(a); a.click(); a.remove();\n    setTimeout(()=>URL.revokeObjectURL(url),60000);\n    toast('تم تحميل الملف');\n  }catch(e){ toast(e.message||'تعذر التحميل'); }\n  btn.disabled=false; btn.textContent='تحميل PDF';\n}\ndocument.addEventListener('click',async e=>{\n  const b=e.target.closest('[data-act]'); if(!b) return;\n  const a=b.dataset.act,id=b.dataset.id;\n  if(a==='authTab'){ S.authTab=b.dataset.v; S.err=''; S.info=''; render(); }\n  else if(a==='logout'){ api('logout',{body:{}}); setToken(null); S.profile=null; S.items=[]; S.view='auth'; render(); }\n  else if(a==='new') startForm(b.dataset.v);\n  else if(a==='back'){ S.view='home'; S.editId=null; render(); }\n  else if(a==='pickTpl'){ F().templateId=id; render(); }\n  else if(a==='edit') startForm(null,S.items.find(x=>x.id===id));\n  else if(a==='download') download(id,b);\n  else if(a==='remind'){ b.disabled=true; const r=await api('requests/'+encodeURIComponent(id)+'/remind',{body:{}}); if(r.ok){ S.items=r.items; render(); toast('وصل التذكير للمرشد'); } else { toast(r.error); b.disabled=false; } }\n  else if(a==='askEdit'){ const box=document.getElementById('ask-'+id); box.hidden=!box.hidden; }\n  else if(a==='sendEdit'){ const t=document.getElementById('ask_'+id).value; b.disabled=true; const r=await api('requests/'+encodeURIComponent(id)+'/message',{body:{text:t}}); if(r.ok){ S.items=r.items; render(); toast('وصل طلب التعديل للمرشد'); } else { toast(r.error); b.disabled=false; } }\n});\nif(S.token) load(); else { S.view='auth'; render(); }\n</script>\n</body>\n</html>\n";
const REMINDER_COOLDOWN_MS = 24 * 3600 * 1000;
const SESSION_DAYS = 30;
const PBKDF2_ITER = 10000;

export default {
  async fetch(req, env) {
    try {
      const url = new URL(req.url);
      const p = url.pathname;
      if (req.method === 'GET' && (p === '/' || p === '/index.html'))
        return new Response(STUDENT_HTML, { headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-cache', 'x-frame-options': 'DENY', 'referrer-policy': 'no-referrer' } });
      if (req.method === 'GET' && p.startsWith('/v/')) return verifyPage(env, decodeURIComponent(p.slice(3)));
      if (req.method === 'GET' && p.startsWith('/brand/')) return brandImage(env, p.split('/')[2], p.split('/')[3]);
      if (req.method === 'GET' && p.startsWith('/doclogo/')) return docLogo(req, env, decodeURIComponent(p.split('/')[2]));
      if (p.startsWith('/api/')) return await routeApi(req, env, p.slice(5));
      return new Response('Not found', { status: 404 });
    } catch (e) {
      return J({ ok: false, error: 'خطأ في الخادم، حاول مرة ثانية.' }, 500);
    }
  }
};

/* ---------------- helpers ---------------- */
const J = (o, s = 200) => new Response(JSON.stringify(o), { status: s, headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' } });
const now = () => Date.now();
const str = (s, max) => String(s == null ? '' : s).trim().slice(0, max || 4000);
const normUser = u => String(u || '').trim().toLowerCase();
const normEmail = e => String(e || '').trim().toLowerCase();
const validEmail = e => /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(e);
const pj = (s, d) => { try { return s ? JSON.parse(s) : d; } catch (e) { return d; } };
function rid(n = 16) { const a = new Uint8Array(n); crypto.getRandomValues(a); return [...a].map(b => b.toString(16).padStart(2, '0')).join(''); }
async function body(req) { try { return await req.json(); } catch (e) { return {}; } }
async function hashPw(pw, salt) {
  const k = await crypto.subtle.importKey('raw', new TextEncoder().encode(pw), 'PBKDF2', false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits({ name: 'PBKDF2', hash: 'SHA-256', salt: new TextEncoder().encode(salt), iterations: PBKDF2_ITER }, k, 256);
  return btoa(String.fromCharCode(...new Uint8Array(bits)));
}
function safeEq(a, b) { a = String(a); b = String(b); if (a.length !== b.length) return false; let r = 0; for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i); return r === 0; }
function validPhoto(ph) { return typeof ph === 'string' && /^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(ph) && ph.length < 80000; }

async function newSession(env, username) {
  const token = rid(24);
  await env.DB.prepare('INSERT INTO sessions (token, username, expires) VALUES (?, ?, ?)').bind(token, username, now() + SESSION_DAYS * 864e5).run();
  if (Math.random() < 0.05) await env.DB.prepare('DELETE FROM sessions WHERE expires < ?').bind(now()).run();
  return token;
}
async function authUser(req, env) {
  const h = req.headers.get('authorization') || '';
  const token = h.startsWith('Bearer ') ? h.slice(7) : '';
  if (!token) return null;
  const s = await env.DB.prepare('SELECT username, expires FROM sessions WHERE token = ?').bind(token).first();
  if (!s || s.expires < now()) return null;
  return env.DB.prepare('SELECT * FROM users WHERE username = ?').bind(s.username).first();
}
const profile = u => ({ username: u.username, name: u.name, email: u.email, photo: u.photo || '' });

function publicItem(r) {
  const input = pj(r.input, {});
  delete input.cvText;
  const fin = pj(r.final, null);
  return {
    id: r.id, type: r.type, status: r.status, createdAt: r.created_at || 0, updatedAt: r.updated_at || 0,
    name: r.name, contactEmail: r.contact_email, gender: r.gender, lang: r.lang, input,
    advisorNote: r.advisor_note || '', studentNote: r.student_note || '',
    approvedAt: r.approved_at || 0, sentAt: r.sent_at || 0, sentTo: r.sent_to || '',
    title: fin && fin.fields ? fin.fields.title : '', program: fin && fin.fields ? fin.fields.program : '',
    reminders: r.reminders || 0, nextReminderAt: r.last_reminder_at ? r.last_reminder_at + REMINDER_COOLDOWN_MS : 0
  };
}
async function listMine(env, username) {
  const { results } = await env.DB.prepare('SELECT * FROM requests WHERE username = ? ORDER BY created_at DESC LIMIT 200').bind(username).all();
  return results.map(publicItem);
}
async function templates(env) {
  const { results } = await env.DB.prepare('SELECT id, label, description, lang, fields FROM templates WHERE active = 1 ORDER BY created_at DESC').all();
  return results.map(t => ({ id: t.id, label: t.label, description: t.description || '', lang: t.lang === 'ar' ? 'ar' : 'en', fields: pj(t.fields, {}) }));
}
function addLog(r, kind, text) {
  const log = pj(r.log, []);
  log.push({ t: now(), by: 'student', kind, text: text || '' });
  return JSON.stringify(log.slice(-40));
}

/* ---------------- API ---------------- */
async function routeApi(req, env, path) {
  const m = req.method;
  if (m === 'POST' && path === 'register') return register(env, await body(req));
  if (m === 'POST' && path === 'login') return login(env, await body(req));
  if (m === 'POST' && path === 'reset') return reset(env, await body(req));

  const u = await authUser(req, env);
  if (!u) return J({ ok: false, error: 'سجّل الدخول من جديد.' }, 401);

  if (m === 'POST' && path === 'logout') {
    const t = (req.headers.get('authorization') || '').slice(7);
    await env.DB.prepare('DELETE FROM sessions WHERE token = ?').bind(t).run();
    return J({ ok: true });
  }
  if (m === 'GET' && path === 'me') return J({ ok: true, profile: profile(u), items: await listMine(env, u.username), templates: await templates(env) });
  if (m === 'POST' && path === 'photo') {
    const b = await body(req);
    if (!validPhoto(b.photo)) return J({ ok: false, error: 'الصورة غير صالحة أو كبيرة.' });
    await env.DB.prepare('UPDATE users SET photo = ? WHERE username = ?').bind(b.photo, u.username).run();
    return J({ ok: true, profile: { ...profile(u), photo: b.photo } });
  }
  if (m === 'POST' && path === 'requests') return createRequest(env, u, await body(req));

  const mm = path.match(/^requests\/([A-Za-z0-9-]+)(?:\/(remind|message|document))?$/);
  if (mm) {
    const r = await env.DB.prepare('SELECT * FROM requests WHERE id = ? AND username = ?').bind(mm[1], u.username).first();
    if (!r) return J({ ok: false, error: 'الطلب غير موجود.' }, 404);
    const act = mm[2];
    if (!act && m === 'PUT') return updateRequest(env, u, r, await body(req));
    if (act === 'remind' && m === 'POST') return remind(env, u, r);
    if (act === 'message' && m === 'POST') return message(env, u, r, await body(req));
    if (act === 'document' && m === 'GET') return documentFor(env, r, new URL(req.url).origin);
  }
  return J({ ok: false, error: 'طلب غير معروف.' }, 404);
}

async function register(env, b) {
  const username = normUser(b.username);
  if (!/^[a-z0-9._-]{3,30}$/.test(username)) return J({ ok: false, error: 'اسم المستخدم من 3 إلى 30 حرف إنجليزي أو رقم (مسموح . _ -).' });
  const name = str(b.name, 160);
  if (!name) return J({ ok: false, error: 'اكتب اسمك الكامل.' });
  const email = normEmail(b.email);
  if (!validEmail(email)) return J({ ok: false, error: 'اكتب إيميل صحيح.' });
  if (String(b.password || '').length < 8) return J({ ok: false, error: 'كلمة المرور لازم تكون 8 أحرف أو أكثر.' });
  if (!validPhoto(b.photo)) return J({ ok: false, error: 'أرفق صورتك الشخصية عشان يتعرف عليك المرشد.' });
  const exists = await env.DB.prepare('SELECT 1 FROM users WHERE username = ?').bind(username).first();
  if (exists) return J({ ok: false, error: 'اسم المستخدم مستخدم، اختر اسم ثاني.' });
  const salt = rid(12);
  await env.DB.prepare('INSERT INTO users (username, name, email, photo, pass_hash, salt, created_at, last_login) VALUES (?, ?, ?, ?, ?, ?, ?, ?)')
    .bind(username, name, email, b.photo, await hashPw(String(b.password), salt), salt, now(), now()).run();
  return J({ ok: true, token: await newSession(env, username) });
}

async function login(env, b) {
  const username = normUser(b.username);
  const u = await env.DB.prepare('SELECT * FROM users WHERE username = ?').bind(username).first();
  if (u && u.locked_until > now()) return J({ ok: false, error: 'محاولات كثيرة. حاول بعد 15 دقيقة.' });
  if (!u || !safeEq(await hashPw(String(b.password || ''), u.salt), u.pass_hash)) {
    if (u) {
      const fails = (u.fails || 0) + 1;
      await env.DB.prepare('UPDATE users SET fails = ?, locked_until = ? WHERE username = ?').bind(fails >= 8 ? 0 : fails, fails >= 8 ? now() + 15 * 60000 : 0, username).run();
    }
    return J({ ok: false, error: 'اسم المستخدم أو كلمة المرور غير صحيحة.' });
  }
  await env.DB.prepare('UPDATE users SET fails = 0, locked_until = 0, last_login = ? WHERE username = ?').bind(now(), username).run();
  return J({ ok: true, token: await newSession(env, username) });
}

/** The advisor creates a 6-digit reset code from the dashboard and gives it to the student. */
async function reset(env, b) {
  const username = normUser(b.username);
  const u = await env.DB.prepare('SELECT * FROM users WHERE username = ?').bind(username).first();
  if (!u || !u.reset_code || (u.reset_expires || 0) < now() || u.locked_until > now()) return J({ ok: false, error: 'الرمز غير صالح أو منتهي. اطلب رمز جديد من المرشد.' });
  if (!safeEq(String(b.code || '').trim(), u.reset_code)) {
    const fails = (u.fails || 0) + 1;
    await env.DB.prepare('UPDATE users SET fails = ?, locked_until = ? WHERE username = ?').bind(fails >= 8 ? 0 : fails, fails >= 8 ? now() + 15 * 60000 : 0, username).run();
    return J({ ok: false, error: 'الرمز غير صحيح.' });
  }
  if (String(b.password || '').length < 8) return J({ ok: false, error: 'كلمة المرور لازم تكون 8 أحرف أو أكثر.' });
  const salt = rid(12);
  await env.DB.prepare('UPDATE users SET pass_hash = ?, salt = ?, reset_code = NULL, reset_expires = NULL, fails = 0, locked_until = 0, last_login = ? WHERE username = ?')
    .bind(await hashPw(String(b.password), salt), salt, now(), username).run();
  await env.DB.prepare('DELETE FROM sessions WHERE username = ?').bind(username).run();
  return J({ ok: true, token: await newSession(env, username) });
}

function common(b) {
  const name = str(b.name, 160);
  if (!name) throw new Error('اكتب اسمك مثل ما تبيه يطلع في الوثيقة.');
  const contact = normEmail(b.contactEmail);
  if (!validEmail(contact)) throw new Error('اكتب إيميل تواصل صحيح.');
  return { name, contact, gender: b.gender === 'f' ? 'f' : 'm', lang: b.lang === 'ar' ? 'ar' : 'en' };
}
async function cleanInput(env, type, b) {
  const i = {};
  if (type === 'cert' && b.templateId) {
    const t = await env.DB.prepare('SELECT * FROM templates WHERE id = ? AND active = 1').bind(String(b.templateId)).first();
    if (!t) throw new Error('هذا النموذج غير متاح الآن.');
    const f = pj(t.fields, {});
    Object.assign(i, { templateId: t.id, templateLabel: t.label, program: f.program || '', achievement: str(b.achievement, 1500),
      polished: { title: f.title || '', lead: f.lead || '', program: f.program || '', body: f.body || '' }, brand: t.brand || '', lang: t.lang === 'ar' ? 'ar' : 'en' });
    return i;
  }
  if (type === 'cert') {
    Object.assign(i, { program: str(b.program, 300), period: str(b.period, 120), achievement: str(b.achievement, 3000) });
    if (!i.achievement) throw new Error('اكتب الإنجاز اللي قدمته.');
    return i;
  }
  const d = b.delivery || {};
  const mode = ['self', 'email', 'platform'].includes(d.mode) ? d.mode : 'self';
  Object.assign(i, {
    target: str(b.target, 400), relationship: str(b.relationship, 1200), achievements: str(b.achievements, 5000), skills: str(b.skills, 2500),
    deadline: /^\d{4}-\d{2}-\d{2}$/.test(String(b.deadline || '')) ? b.deadline : '', cvText: str(b.cvText, 15000), cvName: str(b.cvName, 200),
    delivery: { mode, email: normEmail(d.email), platform: str(d.platform, 200), link: str(d.link, 600), notes: str(d.notes, 1200) }
  });
  if (!i.target) throw new Error('اكتب البرنامج أو الوظيفة اللي تقدم عليها.');
  if (!i.cvText && !i.achievements) throw new Error('ارفع سيرتك الذاتية أو اكتب أهم إنجازاتك.');
  if (mode === 'email' && !validEmail(i.delivery.email)) throw new Error('اكتب إيميل الجهة اللي بتنرسل لها الرسالة.');
  if (mode === 'platform' && !i.delivery.platform) throw new Error('اكتب اسم المنصة.');
  return i;
}

async function createRequest(env, u, b) {
  try {
    const type = b.type === 'rec' ? 'rec' : 'cert';
    const c = common(b);
    const input = await cleanInput(env, type, b);
    if (input.lang) c.lang = input.lang;
    const open = await env.DB.prepare("SELECT COUNT(*) AS n FROM requests WHERE username = ? AND status IN ('submitted','needs_info','edit_requested')").bind(u.username).first();
    if (open.n >= 10) throw new Error('عندك طلبات مفتوحة كثيرة. انتظر المرشد يراجعها.');
    const d = new Date(); const ymd = String(d.getUTCFullYear()).slice(2) + String(d.getUTCMonth() + 1).padStart(2, '0') + String(d.getUTCDate()).padStart(2, '0');
    const id = (type === 'cert' ? 'C' : 'R') + '-' + ymd + '-' + rid(2).toUpperCase();
    const t = now();
    await env.DB.prepare('INSERT INTO requests (id, username, type, status, created_at, updated_at, name, contact_email, gender, lang, input, reminders, log) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?)')
      .bind(id, u.username, type, 'submitted', t, t, c.name, c.contact, c.gender, c.lang, JSON.stringify(input), JSON.stringify([{ t, by: 'student', kind: 'submit' }])).run();
    return J({ ok: true, id, items: await listMine(env, u.username) });
  } catch (e) { return J({ ok: false, error: e.message }); }
}

async function updateRequest(env, u, r, b) {
  try {
    if (!['submitted', 'needs_info'].includes(r.status)) throw new Error('ما تقدر تعدل الطلب بعد ما انعتمد. استخدم "طلب تعديل".');
    const c = common(b);
    const input = await cleanInput(env, r.type, b);
    if (input.lang) c.lang = input.lang;
    const note = str(b.note, 1500) || 'عدّل الطالب بيانات الطلب.';
    await env.DB.prepare('UPDATE requests SET name = ?, contact_email = ?, gender = ?, lang = ?, input = ?, status = ?, student_note = ?, updated_at = ?, log = ? WHERE id = ?')
      .bind(c.name, c.contact, c.gender, c.lang, JSON.stringify(input), 'submitted', note, now(), addLog(r, 'update', note), r.id).run();
    return J({ ok: true, items: await listMine(env, u.username) });
  } catch (e) { return J({ ok: false, error: e.message }); }
}

async function remind(env, u, r) {
  if (['approved', 'rejected'].includes(r.status)) return J({ ok: false, error: 'الطلب منتهي، ما يحتاج تذكير.' });
  if (r.last_reminder_at && now() - r.last_reminder_at < REMINDER_COOLDOWN_MS) return J({ ok: false, error: 'أرسلت تذكير قريب. تقدر ترسل تذكير ثاني بعد 24 ساعة.' });
  await env.DB.prepare('UPDATE requests SET reminders = COALESCE(reminders,0) + 1, last_reminder_at = ?, updated_at = ?, log = ? WHERE id = ?').bind(now(), now(), addLog(r, 'reminder'), r.id).run();
  return J({ ok: true, items: await listMine(env, u.username) });
}

async function message(env, u, r, b) {
  const text = str(b.text, 1500);
  if (!text) return J({ ok: false, error: 'اكتب التعديل اللي تبيه.' });
  const status = ['approved', 'rejected'].includes(r.status) ? 'edit_requested' : r.status;
  await env.DB.prepare('UPDATE requests SET student_note = ?, status = ?, updated_at = ?, log = ? WHERE id = ?').bind(text, status, now(), addLog(r, 'edit_request', text), r.id).run();
  return J({ ok: true, items: await listMine(env, u.username) });
}

/** The approved wording + brand, so the student's browser can build the PDF. */
async function documentFor(env, r, origin) {
  if (r.status !== 'approved' || !r.final) return J({ ok: false, error: 'الوثيقة غير جاهزة بعد.' });
  const f = pj(r.final, {});
  const row = await env.DB.prepare('SELECT data FROM brands WHERE id = ?').bind(f.brandId || '').first();
  const b = pj(row && row.data, {});
  const brand = { ...b };
  for (const k of ['logoTop', 'logoBottom', 'signature']) brand[k] = b[k] ? origin + '/brand/' + encodeURIComponent(f.brandId) + '/' + k : '';
  return J({ ok: true, doc: {
    type: r.type, lang: r.lang, gender: r.gender, name: f.name || r.name, fields: f.fields || {}, letter: f.letter || '',
    brand, extraLogo: f.extraLogo ? origin + '/doclogo/' + encodeURIComponent(r.id) : '', date: r.approved_at, ref: r.id
  } });
}

function dataUriResponse(uri) {
  const m = /^data:([^;]+);base64,(.*)$/.exec(String(uri || ''));
  if (!m) return new Response('Not found', { status: 404 });
  const bin = atob(m[2]); const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new Response(bytes, { headers: { 'content-type': m[1], 'cache-control': 'public, max-age=3600' } });
}
async function brandImage(env, id, key) {
  if (!['logoTop', 'logoBottom', 'signature'].includes(key)) return new Response('Not found', { status: 404 });
  const row = await env.DB.prepare('SELECT data FROM brands WHERE id = ?').bind(decodeURIComponent(id || '')).first();
  return dataUriResponse(pj(row && row.data, {})[key]);
}
async function docLogo(req, env, id) {
  const r = await env.DB.prepare("SELECT final FROM requests WHERE id = ? AND status = 'approved'").bind(id).first();
  return dataUriResponse(pj(r && r.final, {}).extraLogo);
}

/* ---------------- public verification page ---------------- */
async function verifyPage(env, id) {
  const r = /^[A-Za-z0-9-]{4,40}$/.test(id) ? await env.DB.prepare('SELECT id, type, status, name, final, approved_at FROM requests WHERE id = ?').bind(id).first() : null;
  const ok = r && r.status === 'approved';
  const f = ok ? pj(r.final, {}) : {};
  const row = ok ? await env.DB.prepare('SELECT data FROM brands WHERE id = ?').bind(f.brandId || '').first() : null;
  const b = pj(row && row.data, {});
  const e = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const d = ok ? new Date(r.approved_at) : null;
  const html = `<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>التحقق من وثيقة</title>
<style>:root{--bg:#F4F5F2;--s:#fff;--i:#2C2A21;--m:#6C6A5B;--ok:#1F7A4A;--okb:#E2F1E8;--bad:#A23A2E;--badb:#F7E2DE;--fr:#4B4733}
@media (prefers-color-scheme:dark){:root{--bg:#16160F;--s:#201F17;--i:#ECEADF;--m:#A6A392;--ok:#73D19D;--okb:#163223;--bad:#F0948A;--badb:#3A1C18;--fr:#BDB58E;color-scheme:dark}}
body{margin:0;background:var(--bg);color:var(--i);font:16px/1.6 Tahoma,"Segoe UI",sans-serif}main{max-width:520px;margin:40px auto;padding:0 16px}
.c{background:var(--s);border:3px double var(--fr);padding:24px;display:flex;flex-direction:column;gap:12px}.b{padding:8px 12px;border-radius:8px;font-weight:700}
.ok{background:var(--okb);color:var(--ok)}.no{background:var(--badb);color:var(--bad)}dl{display:grid;grid-template-columns:max-content 1fr;gap:6px 14px;margin:0}dt{color:var(--m)}dd{margin:0}</style></head>
<body><main><div class="c"><h1 style="margin:0;font-size:20px">التحقق من وثيقة</h1>
${ok ? `<div class="b ok">وثيقة صحيحة ومعتمدة</div><dl><dt>الرقم</dt><dd>${e(r.id)}</dd><dt>النوع</dt><dd>${r.type === 'rec' ? 'رسالة توصية' : e((f.fields || {}).title || 'شهادة')}</dd>
<dt>باسم</dt><dd>${e(f.name || r.name)}</dd>${r.type !== 'rec' && f.fields && f.fields.program ? `<dt>البرنامج</dt><dd>${e(f.fields.program)}</dd>` : ''}
<dt>أصدرها</dt><dd>${e(b.signatory_en || '')}${b.role_en ? ' — ' + e(b.role_en) : ''}</dd><dt>تاريخ الاعتماد</dt><dd>${d.getUTCDate()}/${d.getUTCMonth() + 1}/${d.getUTCFullYear()}</dd></dl>`
      : `<div class="b no">ما لقينا وثيقة معتمدة بهذا الرقم</div><p style="margin:0;color:var(--m)">تأكد من الرقم المكتوب أسفل الوثيقة.</p>`}
</div></main></body></html>`;
  return new Response(html, { status: ok ? 200 : 404, headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' } });
}
